'use client'

import { createContext, useContext, useEffect, useState, useCallback, ReactNode } from 'react'
import { User, Session } from '@supabase/supabase-js'
import { supabase } from '@/lib/supabase'

// ============================================
// TYPES
// ============================================

export interface Workspace {
    id: string
    name: string
    slug: string
    logo_url?: string
    owner_id: string
    role: 'owner' | 'editor' | 'viewer'
    can_invite: boolean
    brand_access_type: 'all' | 'specific'
}

interface AuthContextType {
    user: User | null
    session: Session | null
    loading: boolean
    workspaces: Workspace[]
    currentWorkspace: Workspace | null
    workspacesLoading: boolean
    signIn: (email: string, password: string) => Promise<{ error: Error | null }>
    signUp: (email: string, password: string, fullName?: string) => Promise<{ error: Error | null }>
    signInWithOAuth: (provider: 'google' | 'github') => Promise<{ error: Error | null }>
    signOut: () => Promise<void>
    switchWorkspace: (workspaceId: string) => void
    createWorkspace: (name: string, slug: string) => Promise<{ data: Workspace | null; error: Error | null }>
    refreshWorkspaces: () => Promise<void>
    // Legacy aliases
    accounts: Workspace[]
    currentAccount: Workspace | null
    authLoading: boolean
    switchAccount: (id: string) => void
    createAccount: (name: string, slug: string) => Promise<{ error: Error | null }>
    refreshAccounts: () => Promise<void>
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

// ============================================
// TIMEOUT HELPER - ensures loading never gets stuck
// ============================================
const TIMEOUT_MS = 5000 // 5 seconds max for any operation

function withTimeout<T>(promise: Promise<T>, fallback: T): Promise<T> {
    return Promise.race([
        promise,
        new Promise<T>((resolve) => setTimeout(() => resolve(fallback), TIMEOUT_MS))
    ])
}

// ============================================
// PROVIDER
// ============================================

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<User | null>(null)
    const [session, setSession] = useState<Session | null>(null)
    const [loading, setLoading] = useState(true)
    const [workspaces, setWorkspaces] = useState<Workspace[]>([])
    const [currentWorkspace, setCurrentWorkspace] = useState<Workspace | null>(null)
    const [workspacesLoading, setWorkspacesLoading] = useState(false) // Start false!

    // ============================================
    // FETCH WORKSPACES - with timeout protection
    // ============================================
    const fetchWorkspaces = useCallback(async (userId: string) => {
        console.log('[Auth] Fetching workspaces for:', userId)
        setWorkspacesLoading(true)

        try {
            // Try RPC - simple and direct, no timeout wrapper needed
            const { data, error: rpcError } = await supabase.rpc('get_user_workspaces')

            if (!rpcError && data && Array.isArray(data) && data.length > 0) {
                console.log('[Auth] Found', data.length, 'workspaces')
                const mapped = data.map((w: any) => ({
                    id: w.workspace_id,
                    name: w.workspace_name,
                    slug: w.workspace_slug,
                    logo_url: w.workspace_logo_url,
                    owner_id: w.is_owner ? userId : '',
                    role: w.role as 'owner' | 'editor' | 'viewer',
                    can_invite: w.can_invite ?? false,
                    brand_access_type: w.brand_access_type ?? 'all'
                }))
                setWorkspaces(mapped)
                selectDefaultWorkspace(mapped)
                return
            }

            console.log('[Auth] No workspaces found, creating one...')
            await createDefaultWorkspace(userId)

        } catch (err) {
            console.error('[Auth] Workspace fetch error:', err)
            // Still try to create workspace on error
            await createDefaultWorkspace(userId)
        } finally {
            // ALWAYS set loading to false
            setWorkspacesLoading(false)
        }
    }, [])

    // Select default workspace
    function selectDefaultWorkspace(workspaceList: Workspace[]) {
        if (workspaceList.length === 0) return

        const savedId = localStorage.getItem('currentWorkspaceId')
        const saved = savedId ? workspaceList.find(w => w.id === savedId) : null

        if (saved) {
            setCurrentWorkspace(saved)
        } else {
            setCurrentWorkspace(workspaceList[0])
            localStorage.setItem('currentWorkspaceId', workspaceList[0].id)
        }
    }

    // Create workspace - direct DB insert, no RPC
    async function createDefaultWorkspace(userId: string) {
        try {
            console.log('[Auth] Creating workspace directly...')

            // Get user email for naming
            const { data: userData } = await supabase.auth.getUser()
            const email = userData?.user?.email || 'user'
            const name = email.split('@')[0]
            const slug = name.toLowerCase().replace(/[^a-z0-9]/g, '-') + '-' + Date.now().toString(36)

            // Create workspace
            const { data: ws, error: wsError } = await supabase
                .from('workspaces')
                .insert({
                    name: `${name}'s Workspace`,
                    slug: slug,
                    owner_id: userId
                })
                .select()
                .single()

            if (wsError) {
                console.error('[Auth] Create workspace failed:', wsError.message)
                return
            }

            // Add membership
            await supabase
                .from('workspace_members')
                .insert({
                    workspace_id: ws.id,
                    user_id: userId,
                    role: 'owner',
                    can_invite: true
                })

            // Set as current
            const workspace: Workspace = {
                id: ws.id,
                name: ws.name,
                slug: ws.slug,
                owner_id: userId,
                role: 'owner',
                can_invite: true,
                brand_access_type: 'all'
            }
            setWorkspaces([workspace])
            setCurrentWorkspace(workspace)
            localStorage.setItem('currentWorkspaceId', ws.id)
            console.log('[Auth] Workspace created:', ws.name)

        } catch (err) {
            console.error('[Auth] Create workspace error:', err)
        }
    }

    // ============================================
    // INITIALIZE AUTH
    // ============================================
    useEffect(() => {
        console.log('[Auth] Initializing...')
        let mounted = true

        // Hard timeout - loading NEVER exceeds 3 seconds
        const hardTimeout = setTimeout(() => {
            if (mounted) {
                console.log('[Auth] Hard timeout - stopping loading')
                setLoading(false)
                setWorkspacesLoading(false)
            }
        }, 3000)

        supabase.auth.getSession().then(({ data: { session } }) => {
            if (!mounted) return

            console.log('[Auth] Session:', session ? 'Found' : 'None')
            setSession(session)
            setUser(session?.user ?? null)
            setLoading(false)

            if (session?.user) {
                fetchWorkspaces(session.user.id)
            }
        })

        const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
            if (!mounted) return

            console.log('[Auth] State change:', event)
            setSession(session)
            setUser(session?.user ?? null)
            setLoading(false)

            if (event === 'SIGNED_IN' && session?.user) {
                fetchWorkspaces(session.user.id)
            } else if (event === 'SIGNED_OUT') {
                setWorkspaces([])
                setCurrentWorkspace(null)
                localStorage.removeItem('currentWorkspaceId')
            }
        })

        return () => {
            mounted = false
            clearTimeout(hardTimeout)
            subscription.unsubscribe()
        }
    }, [fetchWorkspaces])

    // ============================================
    // AUTH ACTIONS
    // ============================================

    const signIn = async (email: string, password: string) => {
        const { error } = await supabase.auth.signInWithPassword({ email, password })
        return { error: error as Error | null }
    }

    const signUp = async (email: string, password: string, fullName?: string) => {
        const { error } = await supabase.auth.signUp({
            email,
            password,
            options: { data: { full_name: fullName } }
        })
        return { error: error as Error | null }
    }

    const signInWithOAuth = async (provider: 'google' | 'github') => {
        const { error } = await supabase.auth.signInWithOAuth({
            provider,
            options: { redirectTo: `${window.location.origin}/auth/callback` }
        })
        return { error: error as Error | null }
    }

    const signOut = async () => {
        await supabase.auth.signOut()
        setWorkspaces([])
        setCurrentWorkspace(null)
    }

    const switchWorkspace = (workspaceId: string) => {
        const ws = workspaces.find(w => w.id === workspaceId)
        if (ws) {
            setCurrentWorkspace(ws)
            localStorage.setItem('currentWorkspaceId', workspaceId)
        }
    }

    const createWorkspace = async (name: string, slug: string) => {
        if (!user) return { data: null, error: new Error('Not authenticated') }

        const { data, error } = await supabase
            .from('workspaces')
            .insert({ name, slug, owner_id: user.id })
            .select()
            .single()

        if (error) return { data: null, error }

        await supabase.from('workspace_members').insert({
            workspace_id: data.id,
            user_id: user.id,
            role: 'owner',
            can_invite: true
        })

        await fetchWorkspaces(user.id)
        return { data: data as Workspace, error: null }
    }

    const refreshWorkspaces = async () => {
        if (user) await fetchWorkspaces(user.id)
    }

    // ============================================
    // CONTEXT VALUE
    // ============================================

    return (
        <AuthContext.Provider value={{
            user,
            session,
            loading,
            workspaces,
            currentWorkspace,
            workspacesLoading,
            signIn,
            signUp,
            signInWithOAuth,
            signOut,
            switchWorkspace,
            createWorkspace,
            refreshWorkspaces,
            // Legacy aliases
            accounts: workspaces,
            currentAccount: currentWorkspace,
            authLoading: loading,
            switchAccount: switchWorkspace,
            createAccount: async (name, slug) => {
                const res = await createWorkspace(name, slug)
                return { error: res.error }
            },
            refreshAccounts: refreshWorkspaces
        }}>
            {children}
        </AuthContext.Provider>
    )
}

// ============================================
// HOOK
// ============================================

export function useAuth() {
    const context = useContext(AuthContext)
    if (context === undefined) {
        throw new Error('useAuth must be used within AuthProvider')
    }
    return context
}
